class SishhinAudio {
 constructor(){this.ctx=null;this.sourceMode=null;this.muted=false;this.last={}}
 async init(){if(this.ctx)return;const ctx=new AudioContext({latencyHint:'interactive'});this.ctx=ctx;try{await ctx.audioWorklet.addModule('pitch-worklet.js')}catch(e){await ctx.close();this.ctx=null;throw e}const gain=v=>{let n=ctx.createGain();n.gain.value=v;return n},filter=(type,f,q=1)=>{let n=ctx.createBiquadFilter();n.type=type;n.frequency.value=f;n.Q.value=q;return n};
 this.input=gain(1);this.raw=ctx.createAnalyser();this.raw.fftSize=4096;this.input.connect(this.raw);this.pitchGate=new AudioWorkletNode(ctx,'pitch-gate',{outputChannelCount:[2]});this.input.connect(this.pitchGate);
 this.comp=ctx.createDynamicsCompressor();this.comp.knee.value=15;this.comp.attack.value=.008;this.comp.release.value=.15;this.pre=gain(1);this.drive=ctx.createWaveShaper();this.drive.oversample='2x';this.driveTone=filter('lowpass',5000,.7);this.driveLevel=gain(1);this.ampPre=gain(1);this.amp=ctx.createWaveShaper();this.amp.oversample='2x';this.bass=filter('lowshelf',150);this.mid=filter('peaking',750,.7);this.treble=filter('highshelf',2500);this.presence=filter('peaking',4200,.6);this.master=gain(.5);this.cabHp=filter('highpass',75,.7);this.cabLp=filter('lowpass',6500,.7);this.cabBody=filter('peaking',130,1.1);this.cabBody.gain.value=3;
 const chain=[this.pitchGate,this.comp,this.pre,this.drive,this.driveTone,this.driveLevel,this.ampPre,this.amp,this.bass,this.mid,this.treble,this.presence,this.master,this.cabHp,this.cabLp,this.cabBody];chain.forEach((n,i)=>{if(i)n&&chain[i-1].connect(n)});
 this.micSum=gain(.6);this.mics=['A','B'].map(()=>{const f=filter('highshelf',2500),d=ctx.createDelay(.1),g=gain(1),p=ctx.createStereoPanner();this.cabBody.connect(f);f.connect(d);d.connect(g);g.connect(p);p.connect(this.micSum);return{f,d,g,p}});
 this.eq=[65,125,250,500,1000,2000,4000,8000,16000].map(f=>filter('peaking',Math.min(f,ctx.sampleRate*.45),1.2));this.hp=filter('highpass',60,.7);this.lp=filter('lowpass',12000,.7);let prev=this.micSum;[...this.eq,this.hp,this.lp].forEach(n=>{prev.connect(n);prev=n});
 this.post=gain(1);prev.connect(this.post);this.delay=ctx.createDelay(2);this.feedback=gain(.3);this.delayTone=filter('lowpass',4000,.7);this.delayWet=gain(0);prev.connect(this.delay);this.delay.connect(this.delayTone);this.delayTone.connect(this.feedback);this.feedback.connect(this.delay);this.delayTone.connect(this.delayWet);this.delayWet.connect(this.post);
 this.reverb=ctx.createConvolver();this.reverbWet=gain(.15);prev.connect(this.reverb);this.reverb.connect(this.reverbWet);this.reverbWet.connect(this.post);this.double=ctx.createDelay(.1);this.doubleGain=gain(0);this.doublePan=ctx.createStereoPanner();this.doublePan.pan.value=.8;this.post.connect(this.double);this.double.connect(this.doubleGain);this.doubleGain.connect(this.doublePan);this.out=gain(.2);this.post.connect(this.out);this.doublePan.connect(this.out);
 this.limit=ctx.createDynamicsCompressor();this.limit.threshold.value=-3;this.limit.knee.value=0;this.limit.ratio.value=20;this.limit.attack.value=.003;this.limit.release.value=.1;this.meter=ctx.createAnalyser();this.meter.fftSize=1024;this.out.connect(this.limit);this.limit.connect(this.meter);this.meter.connect(ctx.destination);this.rawData=new Float32Array(4096);this.meterData=new Float32Array(1024);this.last={};
 }
 async start(mode,s){await this.init();await this.ctx.resume();this.stop();if(mode==='live'){this.stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false,channelCount:2}});this.source=this.ctx.createMediaStreamSource(this.stream)}else{this.source=this.ctx.createBufferSource();this.source.buffer=this.demoBuffer();this.source.loop=true}this.update(s);this.source.connect(this.input);if(mode==='demo')this.source.start();this.sourceMode=mode}
 stop(){if(this.source){try{this.source.stop()}catch{}this.source.disconnect();this.source=null}this.stream?.getTracks().forEach(t=>t.stop());this.stream=null;this.sourceMode=null}
 curve(amount){const a=new Float32Array(2048);for(let i=0;i<a.length;i++){let x=i*2/(a.length-1)-1;a[i]=amount?Math.tanh(x*amount)/Math.tanh(amount):x}return a}
 update(s){if(!this.ctx||!this.input)return;const t=this.ctx.currentTime,sm=(p,v)=>p.setTargetAtTime(v,t,.025),db=v=>Math.pow(10,v/20);sm(this.input.gain,db(s.input));this.pitchGate.port.postMessage({transpose:s.transpose,gateOn:s.gateOn,gate:s.gate,mode:s.mode});this.comp.threshold.value=s.bloomOn?-15-s.bloom*2:0;this.comp.ratio.value=s.bloomOn?2+s.bloom*.6:1;sm(this.pre.gain,s.weightOn?1+s.boost*.28:1);const driveKey=s.edgeOn+':'+s.drive;if(this.last.drive!==driveKey){this.drive.curve=this.curve(s.edgeOn?1+s.drive*.7:0);this.last.drive=driveKey}sm(this.driveTone.frequency,s.edgeOn?1000+s.tone*800:20000);sm(this.driveLevel.gain,s.edgeOn?.35+s.level*.14:1);sm(this.ampPre.gain,[1.1,3,2.5][s.amp]);const ampKey=s.amp+':'+s.gain;if(this.last.amp!==ampKey){this.amp.curve=this.curve([.5,2.3,1.7][s.amp]+s.gain*[.25,1.3,.9][s.amp]);this.last.amp=ampKey}sm(this.bass.gain,(s.bass-5)*2);sm(this.mid.gain,(s.mid-5)*2);sm(this.treble.gain,(s.treble-5)*2);sm(this.presence.gain,(s.presence-5)*1.5);sm(this.master.gain,s.master/10*.7);sm(this.cabHp.frequency,[65,85,55][s.cab]);sm(this.cabLp.frequency,[7400,5900,4800][s.cab]);sm(this.cabBody.frequency,[140,115,95][s.cab]);this.mics.forEach((m,i)=>{const l=i?'B':'A',type=s['mic'+l];sm(m.f.frequency,[3000,2100,4200][type]);sm(m.f.gain,[1,-4,3][type]-s['pos'+l]*7);sm(m.d.delayTime,.001+s['dist'+l]*.018);sm(m.g.gain,db(s['micLevel'+l])*(1-s['dist'+l]*.35));sm(m.p.pan,s['pan'+l])});this.eq.forEach((f,i)=>sm(f.gain,s.eq[i]));sm(this.hp.frequency,s.hp);sm(this.lp.frequency,Math.min(s.lp,this.ctx.sampleRate*.45));sm(this.delay.delayTime,s.delayTime/1000);sm(this.feedback.gain,s.feedback/100);sm(this.delayWet.gain,s.delayOn?s.delayMix/100:0);sm(this.reverbWet.gain,s.reverbOn?s.reverbMix/100:0);if(this.last.decay!==s.decay){this.reverb.buffer=this.impulse(s.decay);this.last.decay=s.decay}sm(this.double.delayTime,s.doubler/1000);sm(this.doubleGain.gain,s.doublerOn?.32:0);sm(this.out.gain,this.muted?0:db(s.output))}
 impulse(seconds){let len=Math.floor(this.ctx.sampleRate*seconds),buf=this.ctx.createBuffer(2,len,this.ctx.sampleRate),seed=8821;for(let c=0;c<2;c++){let d=buf.getChannelData(c),last=0;for(let i=0;i<len;i++){seed=(seed*16807)%2147483647;last=last*.55+(seed/2147483647*2-1)*.45;d[i]=last*Math.pow(1-i/len,2.5)}}return buf}
 demoBuffer(){if(this.demo)return this.demo;const sr=this.ctx.sampleRate,len=sr*8,buf=this.ctx.createBuffer(2,len,sr);let seed=123;const rand=()=>{seed=seed*16807%2147483647;return seed/2147483647*2-1};const add=(time,freq,duration,amp)=>{let n=Math.round(sr/freq),ring=new Float32Array(n);for(let i=0;i<n;i++)ring[i]=rand()*.7;let p=0,last=0,start=Math.floor(time*sr),count=Math.min(Math.floor(duration*sr),len-start);for(let i=0;i<count;i++){let v=ring[p];ring[p]=(v+ring[(p+1)%n])*.496;let fade=Math.min(1,i/80)*Math.min(1,(count-i)/600);for(let c=0;c<2;c++)buf.getChannelData(c)[start+i]+=v*amp*fade;p=(p+1)%n;last=v}};const roots=[82.41,98,110,73.42];for(let bar=0;bar<4;bar++){const root=roots[bar];for(let beat=0;beat<4;beat++){let time=bar*2+beat*.5;add(time,root,beat===3?.35:1.1,.42);add(time+.013,root*1.5,.9,.24);add(time+.026,root*2,.9,.17);if(beat%2)add(time+.25,root,.2,.28)}}this.demo=buf;return buf}
 level(){this.meter.getFloatTimeDomainData(this.meterData);return Math.sqrt(this.meterData.reduce((a,v)=>a+v*v,0)/this.meterData.length)}
 pitch(){this.raw.getFloatTimeDomainData(this.rawData);const d=this.rawData;let rms=Math.sqrt(d.reduce((a,v)=>a+v*v,0)/d.length);if(rms<.005)return null;const sr=this.ctx.sampleRate,min=Math.floor(sr/1200),max=Math.min(1800,Math.floor(sr/45)),size=2048;let best=0,lag=0,prev=1,found=false;for(let k=min;k<max;k++){let a=0,b=0,c=0;for(let i=0;i<size;i+=2){a+=d[i]*d[i+k];b+=d[i]*d[i];c+=d[i+k]*d[i+k]}let corr=a/Math.sqrt(b*c+1e-15);if(corr<.5)found=true;if(found&&corr>best){best=corr;lag=k}if(found&&best>.92&&corr<prev&&k>lag+2)break;prev=corr}return best>.8?sr/lag:null}
}
